package com.ventas.integration;
import com.ventas.service.ReportService;import com.ventas.repository.AuthStore;import com.ventas.dto.ReportModels.Filter;import com.ventas.security.AuthModels.Identity;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="NEGOCIO_DB_INTEGRATION",matches="true")
class ReportDatabaseTest{
 @Autowired ReportService service;@Autowired AuthStore auth;@Autowired Environment env;Identity actor;Filter filter;
 @BeforeEach void setup(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusHours(1));var today=service.dates(actor).hoy();filter=new Filter(today.withDayOfMonth(1),today,null,"",0);}
 @Test void readsSalesAndGeneratesEveryDay(){var r=service.sales(actor,"ventas",filter);assertThat(r.dias()).hasSize(filter.hasta().getDayOfMonth());assertThat(r.resumen()).containsKeys("bruto","anulaciones","devoluciones","neto","costo","margen");}
 @Test void readsInventoryAndCashWithoutChangingBalances(){var inv=service.inventory(actor,filter);assertThat(inv.registros().items()).hasSizeLessThanOrEqualTo(25);assertThat(inv.resumen()).containsKeys("productos","valor");assertThat(service.cash(actor,filter).resumen()).containsKeys("ingresos","egresos","diferencias");}
 @Test void createsAuditedCsvInsideRollbackTransaction(){var result=service.export(actor,"INTEGRATION_ROLLBACK","ventas",filter);assertThat(new String(result,java.nio.charset.StandardCharsets.UTF_8)).contains("fecha;neto;costo;margen");}
}
